import math

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def get_prime_factors(num):
    factors = {}
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def check_divisibility_conditions(n):
    if n < 0:
        return None, None, "n must be non-negative"

    Dn = D(n)

    if Dn == 0:
        return None, None, "D(n) is zero"

    # Check if D(n) is of the form 2^a * 5^b
    factors = get_prime_factors(Dn)

    if len(factors) > 2:
        if 2 not in factors:
            prime2_exists = False
        else:
            prime2_exists = True
        if 5 not in factors:
            prime5_exists = False
        else:
            prime5_exists = True

        if prime2_exists and prime5_exists:
            # Check if there are any other prime factors
            for p in factors:
                if p != 2 and p != 5:
                    return None, None, f"D({n}) has prime factor {p} other than 2 or 5"

        if not (2 in factors and 5 in factors) and Dn > 1:
            # If Dn is not purely 2^a 5^b
            if Dn == 1:
                return 0, 0, "D(n)=1" # Should not happen for n>=0
            return None, None, f"D({n}) is not of the form 2^a 5^b (factors found: {list(factors.keys())})"

    a = factors.get(2, 0)
    b = factors.get(5, 0)

    # Check divisibility conditions
    max_a = 2*n + 2
    max_b = n + 1

    condition_a = a <= max_a
    condition_b = b <= max_b

    return a, b, f"a={a} <= {max_a} ({condition_a}), b={b} <= {max_b} ({condition_b})"

# Test cases
cases = [0, 2, 6]
results = {}
for n in cases:
    a, b, status = check_divisibility_conditions(n)
    results[n] = (a, b, status)

print(results)
